import * as THREE from 'three/webgpu';
import {
    MeshStandardNodeMaterial,
    MeshBasicNodeMaterial,
    smoothstep,
    uv,
    vec3,
    mix,
    add,
    mul,
    contrast,
    saturate,
    texture,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
    const root = new THREE.Object3D();

    // Position / rotation / scale
    if (config.position) root.position.fromArray(config.position);
    if (config.rotation) root.rotation.fromArray(config.rotation);
    if (config.scale) root.scale.fromArray(config.scale);

    // ----- HERO PLANE -------------------------------------------------------
    const PLANE_WIDTH = 4.0;
    const PLANE_HEIGHT = 2.5;
    const SEGMENTS = 64;

    const heroGeo = new THREE.PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT, SEGMENTS, SEGMENTS);
    const heroMat = new MeshStandardNodeMaterial();

    // Load textures (synchronous via cache)
    const colorTex = ctx.textureLoader(config.assets?.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png');
    const depthTex = ctx.textureLoader(config.assets?.depthMapUrl ?? '/prism-mock/home/nodes/parallax-stack.depth.png');

    // Base color node
    heroMat.colorNode = texture(colorTex, uv());

    // Simple filmic grade – contrast up 12%, desaturate 8%, keep red channel
    const contrasted = contrast(heroMat.colorNode, 1.12);
    const desat = saturate(contrasted, 0.92); // 8% desaturation
    heroMat.colorNode = desat;

    // Displacement
    heroMat.displacementNode = mul(texture(depthTex, uv()), 0.18);
    heroMat.displacementScale = 1.0; // scale already baked into node
    heroMat.transparent = true;
    heroMat.opacity = 0.0; // start invisible for fade‑in

    const heroMesh = new THREE.Mesh(heroGeo, heroMat);
    root.add(heroMesh);

    // Apply cinematic primitives
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives?.[prim.name];
            if (typeof fn === 'function') {
                fn(heroMesh, prim.params);
            }
        }
    }

    // ----- BOTTOM SCRIM -----------------------------------------------------
    const scrimMat = new MeshBasicNodeMaterial();
    scrimMat.colorNode = vec3(0x0b0b10 / 0xffffff);
    // opacity = smoothstep(0.45, 1.0, uv().y)  (y=0 bottom, 1 top)
    scrimMat.alphaNode = smoothstep(0.45, 1.0, uv().y);
    scrimMat.transparent = true;

    const scrimGeo = new THREE.PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT);
    const scrimMesh = new THREE.Mesh(scrimGeo, scrimMat);
    scrimMesh.position.z = 0.01; // just above hero plane
    root.add(scrimMesh);

    // ----- CAPTION BLOCK ----------------------------------------------------
    const caption = new THREE.Object3D();
    const padding = 0.5; // base unit = 0.25 → 2× = 0.5
    const baseline = 0.25;
    const startX = -PLANE_WIDTH / 2 + padding;
    const startY = -PLANE_HEIGHT / 2 + padding;

    const texts = [
        {
            content: 'NOVA ATELIER / GENEVA',
            style: config.typography?.kicker,
            color: 0xe8ecf2,
        },
        {
            content: 'Time, Machined.',
            style: config.typography?.headline,
            color: 0xe8ecf2,
        },
        {
            content: 'Every case begins as a single billet of 904L steel.',
            style: config.typography?.body,
            color: 0xe8ecf2,
        },
        {
            content: 'CALIBRE NA-01 / 72 HOUR RESERVE',
            style: config.typography?.caption,
            color: 0xe8ecf2,
        },
    ];

    let cursorY = startY;
    let lineIndex = 0;

    for (const txt of texts) {
        const sz = (txt.style?.fontSize ?? 10) * 0.001; // rough conversion to scene units
        const mesh = ctx.text.createTextMesh(txt.content, {
            fontFamily: txt.style?.family ?? 'sans-serif',
            size: sz,
            weight: txt.style?.fontWeight ?? 400,
            letterSpacing: txt.style?.letterSpacing ?? 0,
            lineHeight: txt.style?.lineHeight ?? 1,
            color: txt.color,
        });

        mesh.position.set(startX, cursorY + lineIndex * baseline, 0.02);
        caption.add(mesh);
        lineIndex++;
    }

    // Accent hairline bar between headline and body (after second line)
    const barWidth = 0.75;
    const barHeight = 0.02;
    const barGeo = new THREE.PlaneGeometry(barWidth, barHeight);
    const barMat = new MeshStandardNodeMaterial({
        emissive: new THREE.Color('#ff2a38'),
        emissiveIntensity: 1.8,
    });
    const barMesh = new THREE.Mesh(barGeo, barMat);
    // Position: after headline (index 1) plus half baseline
    const barY = startY + 1 * baseline + baseline * 0.5;
    barMesh.position.set(startX + barWidth / 2, barY, 0.02);
    caption.add(barMesh);

    root.add(caption);

    // ----- ANIMATIONS -------------------------------------------------------
    const tl = gsap.timeline();
    tl.to(heroMat, {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
    tl.fromTo(
        caption.position,
        { y: caption.position.y + 0.4 },
        {
            y: caption.position.y,
            duration: 0.7,
            ease: 'cubic-bezier(0.215,0.61,0.355,1)',
            delay: 0.12,
        }
    );

    // ----- CLEANUP ---------------------------------------------------------
    root.userData.handlers = {};
    root.userData.cleanup = () => {
        tl.kill();

        heroGeo.dispose();
        heroMat.dispose();

        scrimGeo.dispose();
        scrimMat.dispose();

        barGeo.dispose();
        barMat.dispose();

        caption.traverse((child) => {
            if (child.isMesh) {
                child.geometry.dispose();
                child.material.dispose();
            }
        });
    };

    return root;
}
